export const messages=Object.fromEntries(languages.map((lang,i)=>[lang,Object.fromEntries(Object.entries(messageRows).map(([key,row])=>[key,row[i]]))]));
export function translate(text,language='ko'){if(language==='ko')return String(text);const col=languages.indexOf(language);if(col<1)return String(text);let out=String(text);for(const row of [...catalog].sort((a,b)=>b[0].length-a[0].length))out=out.replaceAll(row[0],()=>row[col]);return out;}
